window.piConnectSession = function (channel) {
  channel = String(channel || '').toLowerCase();
  if (channel === 'airbnb') return piConnectAirbnbInApp();
  if (channel === 'booking' || channel === 'bdc') return piConnectBookingInApp();
  return piConnectSessionPaste(channel);
};
function piRenderBookingConnect(job) {
  var box = document.getElementById('pi-booking-connect');
  if (!box) return;
  if (!job) { box.style.display = 'none'; box.innerHTML = ''; window._piBookingConnectStatus = ''; return; }
  box.style.display = 'block';
  var st = String(job.status || '');
  if ((st === 'interactive' || st === 'starting' || st === 'logging_in') && document.getElementById('pi-booking-browser')) {
    var liveHint = document.getElementById('pi-booking-browser-hint');
    if (liveHint && job.hint) liveHint.textContent = job.hint;
    var liveImg = document.getElementById('pi-booking-browser');
    var liveRev = (job.interactive && job.interactive.rev) || Date.now();
    if (liveImg && liveImg.getAttribute('data-rev') !== String(liveRev)) {
      liveImg.setAttribute('data-rev', String(liveRev));
      liveImg.style.opacity = '1';
      liveImg.src = '/api/platform-invoices/sessions/booking/login/' + encodeURIComponent(job.id) + '/browser.png?v=' + liveRev;
    }
    window._piBookingConnectStatus = st;
    return;
  }
  var body = '';
  if (st === 'starting' || st === 'logging_in') {
    body = '<div style="font-weight:600;margin-bottom:6px">Connecting Booking.com…</div>' +
      '<div style="color:var(--tx3);font-size:12.5px">' + (job.hint || 'Opening admin.booking.com…') + '</div>' +
      '<div style="margin-top:10px"><button class="btn sm" onclick="piCancelBookingConnect()">Cancel</button></div>';
  } else if (st === 'interactive') {
    var browserRev = (job.interactive && job.interactive.rev) || Date.now();
    body = '<div style="font-weight:600;margin-bottom:6px">Operate Booking.com Extranet</div>' +
      '<div id="pi-booking-browser-hint" style="font-size:12.5px;line-height:1.45;margin-bottom:8px">' +
      (job.hint || 'Log into admin.booking.com. When Finance / the Extranet is visible, click Save session for Pull.') + '</div>' +
      '<div style="font-size:11px;color:var(--tx3);margin-bottom:6px">This browser is running on the server. Use <b>admin.booking.com</b> (not www.booking.com). Do not paste JSON.</div>' +
      '<img id="pi-booking-browser" alt="Interactive Booking.com browser" data-rev="' + browserRev + '" ' +
      'src="/api/platform-invoices/sessions/booking/login/' + encodeURIComponent(job.id) + '/browser.png?v=' + browserRev + '" ' +
      'onclick="piBookingBrowserClick(event)" ' +
      'style="display:block;width:100%;max-width:720px;height:auto;border:1px solid var(--bdr);border-radius:8px;cursor:crosshair;background:#fff" />' +
      '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-top:8px">' +
      '<input id="pi-booking-browser-text" type="text" autocomplete="off" placeholder="Type into focused Booking.com field" ' +
      'style="min-width:230px;flex:1;padding:7px 9px;border:1px solid var(--bdr);border-radius:8px;background:var(--bg2)" ' +
      'onkeydown="if(event.key===\'Enter\'){event.preventDefault();piBookingBrowserType();}" />' +
      '<button class="btn gold sm" onclick="piBookingBrowserType()">Type</button>' +
      '<button class="btn sm" onclick="piBookingBrowserKey(\'Enter\')">Enter</button>' +
      '<button class="btn sm" onclick="piBookingBrowserKey(\'Tab\')">Tab</button>' +
      '<button class="btn sm" onclick="piBookingBrowserKey(\'Backspace\')">⌫</button>' +
      '<button class="btn sm" onclick="piBookingBrowserRefresh()">Refresh screen</button>' +
      '<button class="btn gold sm" onclick="piBookingBrowserSave()">Save session for Pull</button>' +
      '<button class="btn sm" onclick="piCancelBookingConnect()">Cancel</button>' +
      '</div>' +
      '<div style="font-size:10.5px;color:var(--tx3);margin-top:5px">Tip: click a field in the image, type in the box above, then press Type or Enter. Password values go only to this Booking.com browser.</div>';
  } else if (st === 'connected') {
    body = '<div style="font-weight:600;color:var(--tx-ok,#059669)">✓ Booking.com connected</div>' +
      '<div style="color:var(--tx3);font-size:12.5px;margin-top:4px">' + (job.hint || 'You can Pull Booking.com now.') + '</div>';
  } else if (st === 'error') {
    body = '<div style="font-weight:600;color:var(--tx-err,#b91c1c)">Connect failed</div>' +
      '<div style="font-size:12.5px;margin-top:4px">' + (job.error || 'Unknown error') + '</div>' +
      (job.pageSnippet ? ('<div style="font-size:11px;color:var(--tx3);margin-top:6px;line-height:1.35">Booking.com page: ' + String(job.pageSnippet).replace(/</g,'&lt;').slice(0,180) + '</div>') : '') +
      '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">' +
      '<button class="btn sm gold" onclick="piConnectBookingInApp()">Try again</button>' +
      '<button class="btn sm" onclick="piCancelBookingConnect()">Cancel</button></div>';
  }
  box.innerHTML = body;
  window._piBookingConnectStatus = st;
}
window.piBookingBrowserRender = function (job) {
  if (job) piRenderBookingConnect(job);
  if (job && job.status === 'connected') {
    if (window._piBookingLoginTimer) { clearInterval(window._piBookingLoginTimer); window._piBookingLoginTimer = null; }
    msg('Booking.com connected — session saved for Pull', true);
    piReload();
  }
};
window.piBookingBrowserRequest = async function (path, payload) {
  var id = window._piBookingLoginId;
  if (!id) throw new Error('No active Booking.com browser');
  var res = await fetch('/api/platform-invoices/sessions/booking/login/' + encodeURIComponent(id) + '/browser/' + path, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload || {})
  });
  var j = await res.json();
  if (!res.ok) throw new Error((j && j.error) || 'Booking.com browser action failed');
  piBookingBrowserRender(j.job);
  return j;
};
window.piBookingBrowserClick = async function (ev) {
  var img = ev && ev.currentTarget;
  if (!img) return;
  var rect = img.getBoundingClientRect();
  var x = Math.round((ev.clientX - rect.left) * (img.naturalWidth || 1440) / rect.width);
  var y = Math.round((ev.clientY - rect.top) * (img.naturalHeight || 900) / rect.height);
  img.style.opacity = '0.55';
  try { await piBookingBrowserRequest('click', { x: x, y: y }); }
  catch (e) { img.style.opacity = '1'; msg(e.message || String(e), false); }
};
window.piBookingBrowserType = async function () {
  var input = document.getElementById('pi-booking-browser-text');
  var text = input ? String(input.value || '') : '';
  if (!text) { msg('Type a value first', false); return; }
  if (input) { input.value = ''; input.disabled = true; }
  try { await piBookingBrowserRequest('type', { text: text }); }
  catch (e) { msg(e.message || String(e), false); }
  finally { if (input) input.disabled = false; }
};
window.piBookingBrowserKey = async function (key) {
  try { await piBookingBrowserRequest('key', { key: key }); }
  catch (e) { msg(e.message || String(e), false); }
};
window.piBookingBrowserRefresh = async function () {
  try { await piBookingBrowserRequest('refresh', {}); }
  catch (e) { msg(e.message || String(e), false); }
};
window.piBookingBrowserSave = async function () {
  try {
    var j = await piBookingBrowserRequest('save', {});
    if (j && j.job && (j.job.status === 'connected' || j.job.sessionSaved)) {
      msg('Booking.com session saved — you can Pull Booking.com now', true);
    }
  } catch (e) { msg(e.message || String(e), false); }
};
window.piCancelBookingConnect = async function () {
  var id = window._piBookingLoginId;
  if (id) {
    try { await fetch('/api/platform-invoices/sessions/booking/login/' + encodeURIComponent(id) + '/cancel', { method: 'POST' }); } catch (e) {}
  }
  window._piBookingLoginId = null;
  if (window._piBookingLoginTimer) { clearInterval(window._piBookingLoginTimer); window._piBookingLoginTimer = null; }
  piRenderBookingConnect(null);
};
window.piPollBookingConnect = async function () {
  var id = window._piBookingLoginId;
  if (!id) return;
  try {
    var res = await fetch('/api/platform-invoices/sessions/booking/login/' + encodeURIComponent(id));
    var raw = await res.text();
    var r = null;
    try { r = JSON.parse(raw); } catch (e) { throw new Error('Connect poll returned non-JSON (' + res.status + ')'); }
    if (!r.ok || !r.job) throw new Error((r && r.error) || 'poll failed');
    var browserImg = document.getElementById('pi-booking-browser');
    if (browserImg && r.job.status !== 'connected' && r.job.status !== 'error') {
      piRenderBookingConnect(r.job);
    } else {
      piRenderBookingConnect(r.job);
    }
    if (r.job.status === 'connected') {
      if (window._piBookingLoginTimer) { clearInterval(window._piBookingLoginTimer); window._piBookingLoginTimer = null; }
      msg('Booking.com connected — session saved for Pull', true);
      await piReload();
      setTimeout(function () { piRenderBookingConnect(null); }, 2500);
    } else if (r.job.status === 'error') {
      if (window._piBookingLoginTimer) { clearInterval(window._piBookingLoginTimer); window._piBookingLoginTimer = null; }
      msg(r.job.error || 'Connect failed', false);
    }
  } catch (e) {
    msg(e.message || String(e), false);
  }
};
window.piConnectBookingInApp = async function () {
  msg('Starting Booking.com connect…', true);
  try {
    var res = await fetch('/api/platform-invoices/sessions/booking/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}'
    });
    var raw = await res.text();
    var j = null;
    try { j = JSON.parse(raw); } catch (e) {
      throw new Error('Connect API returned non-JSON (' + res.status + '). Hard-refresh and retry.');
    }
    if (!res.ok || !j.ok) throw new Error((j && j.error) || (j && j.hint) || 'connect start failed');
    window._piBookingLoginId = j.job && j.job.id;
    piRenderBookingConnect(j.job);
    if (window._piBookingLoginTimer) clearInterval(window._piBookingLoginTimer);
    window._piBookingLoginTimer = setInterval(function () { piPollBookingConnect(); }, 2000);
    await piPollBookingConnect();
  } catch (e) {
    msg(e.message || String(e), false);
    piRenderBookingConnect({ status: 'error', error: e.message || String(e) });
  }
};
